import React, { useState } from 'react';
import { S, C } from './styles';

export const algorithmsData = [
    {
        id: "lr",
        name: "Linear Regression",
        icon: "📈",
        definition: "Predicts continuous values by fitting a straight line.",
        useCases: "Sales, Prices, Trends",
        advantages: "Fast, Highly Interpretable",
        disadvantages: "Assumes linearity, Outlier sensitive",
        complexity: "Low",
        interpretability: "High",
        trainingTime: "Very Fast"
    },
    {
        id: "logr",
        name: "Logistic Regression",
        icon: "S",
        definition: "Predicts class probabilities using a sigmoid curve.",
        useCases: "Spam Detection, Binary Medical Dx",
        advantages: "Outputs probabilities, Fast",
        disadvantages: "Fails with non-linear bounds",
        complexity: "Low",
        interpretability: "High",
        trainingTime: "Very Fast"
    },
    {
        id: "dt",
        name: "Decision Tree",
        icon: "🌳",
        definition: "Splits data iteratively based on feature thresholds.",
        useCases: "Credit Scoring, Simple Rules",
        advantages: "No scaling needed, Interpretable",
        disadvantages: "Prone to Overfitting, Unstable",
        complexity: "Medium",
        interpretability: "High",
        trainingTime: "Fast"
    },
    {
        id: "rf",
        name: "Random Forest",
        icon: "🌲",
        definition: "Ensemble of decision trees voting on the outcome.",
        useCases: "Fraud Detection, Churn",
        advantages: "High accuracy, Handles missing data",
        disadvantages: "Black box, Computationally heavy",
        complexity: "High",
        interpretability: "Low",
        trainingTime: "Slow"
    },
    {
        id: "svm",
        name: "Support Vector Machine",
        icon: "⊘",
        definition: "Finds the hyper-plane maximizing margin between classes.",
        useCases: "Text Class., Image Recognition",
        advantages: "Effective in high-dims, Memory efficient",
        disadvantages: "Slow on large datasets, High memory during train",
        complexity: "High",
        interpretability: "Medium",
        trainingTime: "Moderate"
    },
    {
        id: "knn",
        name: "K-Nearest Neighbors",
        icon: "⊕",
        definition: "Predicts based on the 'K' closest data points in space.",
        useCases: "Recommender Systems",
        advantages: "Zero training phase, Intuitive",
        disadvantages: "Slow inference, Dimensionality curse",
        complexity: "Low",
        interpretability: "Medium",
        trainingTime: "Zero (Lazy)"
    },
    {
        id: "nn",
        name: "Neural Network",
        icon: "◉",
        definition: "Layers of interconnected nodes mapping inputs to outputs.",
        useCases: "Computer Vision, NLP",
        advantages: "Handles complex non-linear data",
        disadvantages: "Needs high data volume, Compute intensive",
        complexity: "Very High",
        interpretability: "Very Low",
        trainingTime: "Slowest"
    },
    {
        id: "km",
        name: "K-Means",
        icon: "◎",
        definition: "Partitions data into K distinct non-overlapping clusters.",
        useCases: "Cust. Segmentation",
        advantages: "Fast, Scales well",
        disadvantages: "Sensitive to init, Assumes spherical clusters",
        complexity: "Medium",
        interpretability: "Medium",
        trainingTime: "Fast"
    }
];

const Tooltip = ({ text, children }) => {
    const [show, setShow] = useState(false);
    return (
        <div style={{ position: "relative", display: "inline-block", cursor: "help" }} onMouseEnter={() => setShow(true)} onMouseLeave={() => setShow(false)}>
            {children}
            {show && (
                <div style={{
                    position: "absolute", bottom: "100%", left: "50%", transform: "translateX(-50%)",
                    background: C.surfaceDeep, padding: "8px 12px", borderRadius: 6, border: `1px solid ${C.accent}`,
                    color: C.text, fontSize: 10, whiteSpace: "nowrap", zIndex: 100,
                    boxShadow: `0 0 15px ${C.accentDim}`, marginBottom: 6, fontFamily: "Space Mono",
                    pointerEvents: "none"
                }}>
                    {text}
                </div>
            )}
        </div>
    );
};

export default function MLComparisonPanel() {
    const [isOpen, setIsOpen] = useState(false);
    const [selected, setSelected] = useState(["lr", "dt"]);

    const toggleSelection = (id) => {
        if (selected.includes(id)) {
            setSelected(selected.filter(i => i !== id));
        } else {
            if (selected.length < 3) setSelected([...selected, id]);
        }
    };

    const getMetricColor = (key, val) => {
        const v = val.toLowerCase();
        if (key === "interpretability") {
            if (v.includes("high")) return C.accent;
            if (v.includes("low")) return C.danger;
            return C.warn;
        }
        if (key === "complexity") {
            if (v.includes("high")) return C.danger;
            if (v.includes("low")) return C.accent;
            return C.warn;
        }
        if (key === "trainingTime") {
            if (v.includes("fast")) return C.accent;
            if (v.includes("slow")) return C.danger;
            return C.warn;
        }
        return C.text;
    };

    return (
        <>
            {/* Toggle Button */}
            <div
                onClick={() => setIsOpen(!isOpen)}
                style={{
                    position: "fixed",
                    right: isOpen ? 450 : 0,
                    top: "50%",
                    transform: "translateY(-50%)",
                    padding: "24px 8px",
                    background: "rgba(5,12,22,0.95)",
                    border: `1px solid ${C.border}`,
                    borderRight: "none",
                    borderRadius: "12px 0 0 12px",
                    cursor: "pointer",
                    backdropFilter: "blur(10px)",
                    color: C.accent,
                    writingMode: "vertical-rl",
                    textOrientation: "mixed",
                    letterSpacing: 2,
                    fontFamily: "Orbitron",
                    fontSize: 12,
                    boxShadow: `-4px 0 20px rgba(0,255,180,0.15)`,
                    zIndex: 100,
                    transition: "right 0.3s cubic-bezier(0.4,0,0.2,1)",
                }}
            >
                {isOpen ? "▶ HIDE COMPARISON" : "◀ COMPARE ALGOS"}
            </div>

            {/* Panel */}
            <div style={{
                position: "fixed",
                right: isOpen ? 0 : -450,
                top: 0,
                bottom: 0,
                width: 450,
                background: "rgba(5,12,22,0.95)",
                borderLeft: `1px solid ${C.border}`,
                boxShadow: `-10px 0 40px rgba(0,0,0,0.9)`,
                backdropFilter: "blur(15px)",
                transition: "right 0.3s cubic-bezier(0.4,0,0.2,1)",
                zIndex: 99,
                display: "flex",
                flexDirection: "column",
            }}>
                {/* Header */}
                <div style={{ padding: "24px", borderBottom: `1px solid ${C.border}`, flexShrink: 0 }}>
                    <h2 style={{ fontFamily: "Orbitron", margin: 0, color: C.accent, fontSize: 18, letterSpacing: 1.5, display: "flex", alignItems: "center", gap: 10 }}>
                        <span style={{ fontSize: 22 }}>⚖️</span> COMPARISON PANEL
                    </h2>
                    <p style={{ fontSize: 11, color: C.textDim, marginTop: 8, lineHeight: 1.5, fontFamily: "Space Mono" }}>
                        Select up to <strong style={{ color: C.accent }}>3</strong> models below to compare their strengths, weaknesses, and use cases.
                    </p>

                    {/* Algorithm Selector */}
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 16 }}>
                        {algorithmsData.map(algo => {
                            const isActive = selected.includes(algo.id);
                            const isDisabled = !isActive && selected.length >= 3;
                            return (
                                <button
                                    key={algo.id}
                                    onClick={() => toggleSelection(algo.id)}
                                    disabled={isDisabled}
                                    style={{
                                        padding: "6px 12px", borderRadius: 20,
                                        border: `1px solid ${isActive ? C.accent : C.border}`,
                                        background: isActive ? C.accentDim : "rgba(255,255,255,0.03)",
                                        color: isActive ? C.accent : (isDisabled ? "rgba(200,230,245,0.2)" : C.textDim),
                                        cursor: isDisabled ? "not-allowed" : "pointer",
                                        fontSize: 10, fontFamily: "Space Mono", fontWeight: isActive ? 700 : 400,
                                        transition: "all 0.2s",
                                        display: "flex", alignItems: "center", gap: 6
                                    }}
                                >
                                    <span style={{ fontSize: 12 }}>{algo.icon}</span> {algo.name}
                                </button>
                            )
                        })}
                    </div>
                </div>

                {/* Comparison Content */}
                <div style={{ flex: 1, overflowY: "auto", padding: "24px" }}>
                    {selected.length === 0 ? (
                        <div style={{ textAlign: "center", color: C.textMuted, marginTop: 60, fontSize: 12, fontFamily: "Space Mono" }}>
                            <div style={{ fontSize: 40, opacity: 0.5, marginBottom: 16 }}>🎯</div>
                            Please select an algorithm to begin comparison...
                        </div>
                    ) : (
                        <div style={{ display: "grid", gridTemplateColumns: `110px repeat(${selected.length}, 1fr)`, gap: "10px", alignItems: "start" }}>

                            {/* Headings */}
                            <div style={S.label}>Feature</div>
                            {selected.map(id => {
                                const a = algorithmsData.find(x => x.id === id);
                                return (
                                    <div key={id} style={{ color: C.text, fontWeight: 700, textAlign: "center", fontFamily: "Orbitron", fontSize: 11, letterSpacing: 1 }}>
                                        <div style={{ fontSize: 20, marginBottom: 4 }}>{a.icon}</div>
                                        {a.name.toUpperCase()}
                                    </div>
                                )
                            })}

                            {/* Rows */}
                            {[
                                { key: "definition", label: "Definition", tooltip: "High-level intuition behind how the model learns from data." },
                                { key: "useCases", label: "Best Use Cases", tooltip: "Real-world scenarios where this algorithm excels." },
                                { key: "advantages", label: "Advantages", tooltip: "What makes this algorithm a strong or robust choice?" },
                                { key: "disadvantages", label: "Disadvantages", tooltip: "What are the algorithm's main limitations or vulnerabilities?" },
                                { key: "complexity", label: "Complexity", tooltip: "How mathematically intense is it? How hard is it to tune hyperparameters?" },
                                { key: "interpretability", label: "Interpretability", tooltip: "How easy is it for a human to understand why it made a specific prediction?" },
                                { key: "trainingTime", label: "Training Time", tooltip: "How fast is the learning phase on large datasets?" }
                            ].map(row => (
                                <React.Fragment key={row.key}>
                                    {/* Row Label */}
                                    <div style={{ padding: "16px 0", borderBottom: `1px solid rgba(0,255,180,0.1)`, display: "flex", alignItems: "center" }}>
                                        <Tooltip text={row.tooltip}>
                                            <span style={{ color: C.textDim, fontSize: 10, borderBottom: `1px dashed rgba(200,230,245,0.3)`, fontFamily: "Space Mono", textTransform: "uppercase", letterSpacing: 0.5, lineHeight: 1.4 }}>
                                                {row.label}
                                            </span>
                                        </Tooltip>
                                    </div>

                                    {/* Values */}
                                    {selected.map(id => {
                                        const a = algorithmsData.find(x => x.id === id);
                                        const val = a[row.key];
                                        let style = {
                                            padding: "16px 8px", borderBottom: `1px solid rgba(0,255,180,0.1)`,
                                            textAlign: "center", fontSize: 11, lineHeight: 1.6,
                                            fontFamily: "Space Mono", color: "rgba(200,230,245,0.85)"
                                        };

                                        // Custom styling for badged metrics
                                        if (row.key === "complexity" || row.key === "interpretability" || row.key === "trainingTime") {
                                            const color = getMetricColor(row.key, val);
                                            return (
                                                <div key={id} style={{ ...style, display: "flex", justifyContent: "center", alignItems: "center" }}>
                                                    <span style={{
                                                        padding: "4px 8px", borderRadius: 6,
                                                        background: color + "15", color: color,
                                                        border: `1px solid ${color}40`, fontWeight: 700,
                                                        fontSize: 10, letterSpacing: 0.5, textTransform: "uppercase"
                                                    }}>
                                                        {val}
                                                    </span>
                                                </div>
                                            )
                                        }

                                        return <div key={id} style={style}>{val}</div>
                                    })}
                                </React.Fragment>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </>
    );
}
